function grid$syscodechange(f){
  this.constructor(f);
}
grid$syscodechange.prototype = new DirEvent();
grid$syscodechange.prototype.afterInit = function() {
  var p = this._dir;
}
grid$syscodechange.prototype.beforeButtonGridClick = function (id, gindex, r) {
  var p = this._dir, g = p.grid(), time = $.userinfo.val('ProcessTimeout');;
  switch (id) {
    case 'runrow':
      if (r == null || p.valGrid(r, 'status', gindex) != 5) return
      $.question('$sureChangeCode', $.msg.get("QuestionTitle"), p, function (q, v) {
        q._close();
        if (v) {
          p.grequest(gindex, 'RunRow', '', ['id', 'code_type', 'old_value', 'new_value'], function(){
            p._refresh();
          }, r, time)
        }
      });
      return false;
      break;
    case 'runall':
      $.question('$sureChangeCode', $.msg.get("QuestionTitle"), p, function (q, v) {
        q._close();
        if (v) {
          p.grequest(gindex, 'RunAll', '', ['id', 'code_type', 'old_value', 'new_value'], function(){
            p._refresh();
          }, r, time)
        }
      });
      return false;
      break;
    default:
      break;
  }
  return true;
}
